begin;
do $patch$
declare definition text;
begin
 select pg_get_functiondef('public.sanji_email_tracking_report(uuid,timestamptz,timestamptz,uuid,boolean,uuid)'::regprocedure) into definition;
 if position('manual_reply' in definition)>0 then return;end if;
 definition:=replace(definition,'coalesce(reply.positive,false) positive_reply','coalesce(reply.positive,false) positive_reply,coalesce(reply.manual,false) manual_reply,coalesce(reply.email,false) email_reply');
 definition:=replace(definition,$old$bool_or(exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) m where m->>'out'='false'$old$,$new$bool_or(exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) m where m->>'out'='false'$new$);
 definition:=replace(definition,$old$bool_or(exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) m where m->>'out'='false' and coalesce(m->>'automatic','false')<>'true' and m->>'inReplyTo'='<'||(o.data->>'messageId')||'@sanji.local>'$old$,$new$bool_or(r.data->>'channel'='email' and exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) m where m->>'out'='false' and coalesce(m->>'automatic','false')<>'true' and (m->>'inReplyTo'='<'||(o.data->>'messageId')||'@sanji.local>' or exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) original where original->>'out'='true' and original->>'outboxId'=o.id::text and original->>'messageId'=m->>'inReplyTo'))$new$);
 definition:=replace(definition,$old$ from public.sanji_records r where r.owner=o.owner and r.kind='thread' and r.data->>'channel'='email'$old$,$new$,bool_or(r.data->>'channel' in('sms','phone','manual') and exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) m where m->>'out'='false' and coalesce(m->>'automatic','false')<>'true' and (m->>'at')::timestamptz>=o.created)) manual, bool_or(r.data->>'channel'='email' and exists(select 1 from jsonb_array_elements(coalesce(r.data->'messages','[]')) m where m->>'out'='false' and coalesce(m->>'automatic','false')<>'true' and (m->>'at')::timestamptz>=o.created)) email from public.sanji_records r where r.owner=o.owner and r.kind='thread' and r.data->>'channel' in('email','sms','phone','manual')$new$);
 definition:=replace(definition,$old$and (r.data->>'providerId'=o.data->>'providerThread' or exists$old$,$new$and (r.data->>'channel' in('sms','phone','manual') or r.data->>'providerId'=o.data->>'providerThread' or exists$new$);
 definition:=replace(definition,$old$where sent->>'messageId'='<'||(o.data->>'messageId')||'@sanji.local>'$old$,$new$where sent->>'out'='true' and (sent->>'outboxId'=o.id::text or sent->>'messageId'='<'||(o.data->>'messageId')||'@sanji.local>')$new$);
 definition:=replace(definition,$old$count(*) filter(where status='accepted' and human_reply) human_replied,$old$,$new$count(distinct target) filter(where status='accepted' and email_reply) email_replied_targets, count(distinct target) filter(where status='accepted' and manual_reply) manual_replied_targets, count(*) filter(where status='accepted' and human_reply) human_replied,$new$);
 if position('original->>''outboxId''' in definition)=0 or position('manual_replied_targets' in definition)=0 then raise exception 'Unexpected report definition';end if;
 definition:=replace(definition,$old$count(distinct target) filter(where status='accepted') sent_targets,$old$,$new$count(distinct target) filter(where status='accepted') sent_targets, count(distinct target) filter(where status='accepted' and exists(select 1 from public.sanji_records candidate where candidate.owner=p_owner and candidate.kind='candidate' and candidate.id=rows.target and nullif(candidate.data#>>'{meeting,at}','') is not null)) meeting_targets,$new$);
 execute definition;
end $patch$;
commit;
